def maximum_subarray_sum(nums: List[int], k: int) -> int:
    best = None
    min_prefix = {}       # value -> smallest prefix sum just before an occurrence of it
    prefix = 0
    for x in nums:
        for partner in (x - k, x + k):
            if partner in min_prefix:
                candidate = prefix + x - min_prefix[partner]
                if best is None or candidate > best:
                    best = candidate
        if x not in min_prefix or prefix < min_prefix[x]:
            min_prefix[x] = prefix
        prefix += x
    return 0 if best is None else best

