class TimeLimitedCache:
    def __init__(self):
        self.entries = {}     # key -> (value, expires_at)
        self.expiry = []      # min heap of (expires_at, key); may hold stale pairs
        self.live = 0

    def _purge(self) -> None:
        now = current_time()
        while self.expiry and self.expiry[0][0] <= now:
            expires_at, key = heapq.heappop(self.expiry)
            entry = self.entries.get(key)
            if entry is not None and entry[1] == expires_at:
                del self.entries[key]
                self.live -= 1

    def set(self, key: int, value: int, duration: int) -> bool:
        self._purge()
        existed = key in self.entries
        if not existed:
            self.live += 1
        expires_at = current_time() + duration
        self.entries[key] = (value, expires_at)
        heapq.heappush(self.expiry, (expires_at, key))
        if duration == 0:
            self._purge()     # a zero lifetime entry is never visible
        return existed

    def get(self, key: int) -> int:
        self._purge()
        entry = self.entries.get(key)
        return entry[0] if entry is not None else -1

    def count(self) -> int:
        self._purge()
        return self.live

