def strong_password_checker(password: str) -> int:
    n = len(password)
    missing = 3 - (any(c.islower() for c in password)
                   + any(c.isupper() for c in password)
                   + any(c.isdigit() for c in password))

    replace = 0      # replacements needed to break every run of 3 or more
    mod0 = mod1 = 0  # runs whose length is 0 or 1 modulo 3
    i = 0
    while i < n:
        j = i
        while j < n and password[j] == password[i]:
            j += 1
        run = j - i
        if run >= 3:
            replace += run // 3
            if run % 3 == 0:
                mod0 += 1
            elif run % 3 == 1:
                mod1 += 1
        i = j

    if n < 6:
        return max(missing, 6 - n)
    if n <= 20:
        return max(missing, replace)

    delete = n - 20
    # One deletion saves a replacement on a run with length % 3 == 0.
    replace -= min(delete, mod0)
    # Two deletions save one on a run with length % 3 == 1.
    replace -= min(max(delete - mod0, 0), 2 * mod1) // 2
    # Any further three deletions save one more.
    replace -= max(delete - mod0 - 2 * mod1, 0) // 3
    return delete + max(missing, replace)

def loud_and_rich(richer: List[List[int]], quiet: List[int]) -> List[int]:
    n = len(quiet)
    poorer = [[] for _ in range(n)]
    indegree = [0] * n
    for rich, poor in richer:
        poorer[rich].append(poor)
        indegree[poor] += 1

    answer = list(range(n))      # everyone starts as their own best candidate
    queue = deque(x for x in range(n) if indegree[x] == 0)
    while queue:
        u = queue.popleft()
        for v in poorer[u]:
            # Everyone at least as rich as u is also at least as rich as v.
            if quiet[answer[u]] < quiet[answer[v]]:
                answer[v] = answer[u]
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    return answer

