def can_arrange(arr: list[int], k: int) -> bool:
    # How many items have each remainder modulo k (Python's % is never negative here).
    counts = [0] * k
    for value in arr:
        counts[value % k] += 1

    # Remainder 0 items can only pair with each other.
    if counts[0] % 2:
        return False
    for r in range(1, k // 2 + 1):
        partner = k - r
        if r == partner:
            # Remainder k/2 pairs with itself, so it needs an even count.
            if counts[r] % 2:
                return False
        elif counts[r] != counts[partner]:
            return False
    return True

