def construct(grid: list[list[int]]) -> 'Node':
    def build(r: int, c: int, size: int) -> 'Node':
        if size == 1:
            return Node(grid[r][c] == 1, True)
        half = size // 2
        kids = [build(r, c, half), build(r, c + half, half),
                build(r + half, c, half), build(r + half, c + half, half)]
        # Four leaves with the same value describe a uniform region.
        if all(k.isLeaf for k in kids) and len({k.val for k in kids}) == 1:
            return Node(kids[0].val, True)
        return Node(True, False, *kids)

    return build(0, 0, len(grid))

