def max_value(n: int, index: int, maxSum: int) -> int:
    def side_cost(v: int, length: int) -> int:
        """Minimum sum of `length` cells beside a peak of v, descending to 1."""
        if length < v:
            first = v - length            # values v - length .. v - 1
            return (first + v - 1) * length // 2
        return (v - 1) * v // 2 + (length - (v - 1))  # down to 1, then ones

    def cost(v: int) -> int:
        return v + side_cost(v, index) + side_cost(v, n - 1 - index)

    lo, hi = 1, maxSum
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if cost(mid) <= maxSum:
            lo = mid
        else:
            hi = mid - 1
    return lo

