def eventual_safe_nodes(graph: list[list[int]]) -> list[int]:
    n = len(graph)
    pending = [len(nbrs) for nbrs in graph]   # outgoing edges not yet known to be safe
    parents = [[] for _ in range(n)]
    for u, nbrs in enumerate(graph):
        for v in nbrs:
            parents[v].append(u)

    queue = [u for u in range(n) if pending[u] == 0]   # terminal nodes
    safe = [False] * n
    for u in queue:                    # the list grows while we iterate
        safe[u] = True
        for p in parents[u]:
            pending[p] -= 1
            if pending[p] == 0:
                queue.append(p)
    return [u for u in range(n) if safe[u]]

class FindSumPairs:
    def __init__(self, nums1: list[int], nums2: list[int]):
        self.nums1 = nums1
        self.nums2 = nums2
        self.freq = Counter(nums2)   # value -> occurrences in nums2

    def add(self, index: int, val: int) -> None:
        old = self.nums2[index]
        self.freq[old] -= 1
        self.nums2[index] = old + val
        self.freq[old + val] += 1

    def count(self, tot: int) -> int:
        freq = self.freq
        return sum(freq.get(tot - x, 0) for x in self.nums1)

