def min_operations(nums: list[int], k: int) -> int:
    if min(nums) < k:
        return -1          # values can only go down
    # Each distinct value above k must be flattened by one operation.
    return len({x for x in nums if x > k})

def tictactoe(moves: list[list[int]]) -> str:
    rows = [0, 0, 0]
    cols = [0, 0, 0]
    diag = anti = 0
    for turn, (r, c) in enumerate(moves):
        mark = 1 if turn % 2 == 0 else -1     # A is +1, B is -1
        rows[r] += mark
        cols[c] += mark
        if r == c:
            diag += mark
        if r + c == 2:
            anti += mark
        if 3 in (abs(rows[r]), abs(cols[c]), abs(diag), abs(anti)):
            return "A" if mark == 1 else "B"
    return "Draw" if len(moves) == 9 else "Pending"

