def adapt(ns, args):
    Node = ns["Node"]
    nodes = []
    head = None
    # Build every level iteratively: (items of the level, node that owns it as child).
    stack = [(args[0], None)]
    while stack:
        items, owner = stack.pop()
        first = prev = None
        for item in items:
            if isinstance(item, list):
                val, sub = item
            else:
                val, sub = item, None
            node = Node(val)
            nodes.append(node)
            if prev is None:
                first = node
            else:
                prev.next = node
                node.prev = prev
            prev = node
            if sub:
                stack.append((sub, node))
        if owner is None:
            head = first
        else:
            owner.child = first
    ids = set(id(x) for x in nodes)
    r = ns["flatten"](head)
    if head is None:
        return [] if r is None else "expected None for an empty list"
    if r is not head:
        return "the returned head must be the original first node"
    out = []
    prev = None
    node = r
    while node is not None:
        if len(out) > len(nodes):
            return "the flattened list is longer than the input (is there a cycle?)"
        if id(node) not in ids:
            return "the flattened list contains a node that was not in the input"
        if node.prev is not prev:
            return "the prev pointer of node %d is wrong" % node.val
        if node.child is not None:
            return "the child pointer of node %d was not cleared" % node.val
        out.append(node.val)
        prev = node
        node = node.next
    return out

