def maximum_safeness_factor(grid: list[list[int]]) -> int:
    n = len(grid)
    # Phase 1: distance from every cell to its nearest thief (multi source BFS).
    dist = [[-1] * n for _ in range(n)]
    queue = []
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                dist[r][c] = 0
                queue.append((r, c))
    for r, c in queue:                     # the list grows while we scan it
        d = dist[r][c] + 1
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] < 0:
                dist[nr][nc] = d
                queue.append((nr, nc))

    # Phase 2: maximise the minimum label along the path (max heap via negation).
    seen = [[False] * n for _ in range(n)]
    heap = [(-dist[0][0], 0, 0)]
    seen[0][0] = True
    while heap:
        neg, r, c = heapq.heappop(heap)
        if r == n - 1 and c == n - 1:
            return -neg
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < n and 0 <= nc < n and not seen[nr][nc]:
                seen[nr][nc] = True
                heapq.heappush(heap, (-min(-neg, dist[nr][nc]), nr, nc))
    return 0

class FirstUnique:
    def __init__(self, nums: list[int]):
        self.seen = set()
        self.unique = OrderedDict()     # values seen exactly once, in arrival order
        for x in nums:
            self.add(x)

    def showFirstUnique(self) -> int:
        if self.unique:
            return next(iter(self.unique))
        return -1

    def add(self, value: int) -> None:
        if value not in self.seen:
            self.seen.add(value)
            self.unique[value] = None
        elif value in self.unique:
            # A second copy arrived: it can never be unique again.
            del self.unique[value]

