def get_length_of_optimal_compression(s: str, k: int) -> int:
    n = len(s)

    def encoded(count: int) -> int:
        # Length of "c", "c7", "c42" or "c100".
        if count == 1:
            return 1
        return 1 + len(str(count))

    INF = float("inf")
    # dp[i][r]: best encoded length of s[i:] with r deletions available.
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[n] = [0] * (k + 1)
    for i in range(n - 1, -1, -1):
        nxt_row = dp[i + 1]
        for r in range(k + 1):
            best = nxt_row[r - 1] if r > 0 else INF     # delete s[i]
            same = 0
            for j in range(i, n):
                if s[j] == s[i]:
                    same += 1
                    deleted = j - i + 1 - same
                    cand = encoded(same) + dp[j + 1][r - deleted]
                    if cand < best:
                        best = cand
                elif j - i + 1 - same > r:
                    break                             # too many deletions needed
            dp[i][r] = best
    return dp[0][k]

