def group_strings(strings: list[str]) -> list[list[str]]:
    groups = defaultdict(list)
    for s in strings:
        # Differences between neighbouring letters survive any shift.
        key = tuple((ord(b) - ord(a)) % 26 for a, b in zip(s, s[1:]))
        groups[key].append(s)
    return list(groups.values())

def good_nodes(root: Optional[TreeNode]) -> int:
    if root is None:
        return 0
    count = 0
    stack = [(root, root.val)]          # (node, largest value above or at its parent)
    while stack:
        node, path_max = stack.pop()
        if node.val >= path_max:
            count += 1
        best = max(path_max, node.val)
        if node.left:
            stack.append((node.left, best))
        if node.right:
            stack.append((node.right, best))
    return count
